import base64,hashlib,json
from pathlib import Path
r=Path(__file__).resolve().parents[2]; audit=r/'Examtopics/audit'
qs=json.loads((r/'Examtopics/output/complete_q1_q1396.json').read_text(encoding='utf-8'))
by={q['id']:q for q in qs}
fp=lambda q:hashlib.sha256(json.dumps(q,ensure_ascii=False,sort_keys=True,separators=(',',':')).encode()).hexdigest()
fix={
901:dict(explanation='B。目的地址 172.16.3.254 落入图中直连前缀 `172.16.2.0/23` 的 172.16.2.0–172.16.3.255 范围，/23 对应 255.255.254.0。它比同时匹配的默认路由 /0 更长；图中 /32 项不匹配。源地址不决定普通目的地址路由查找。A 是 /0，C 是 /24，D 是 /32。'),
902:dict(prompt='Refer to the exhibit. The DHCP client reaches its T1 renewal time with its existing IPv4 address still valid. What does it request from its DHCP server?',explanation='B。图中 DHCP 已启用，当前 IPv4 地址为 192.168.69.132。客户端进入 RENEWING 时向原服务器发送 DHCPREQUEST，申请延续当前地址的租约；RFC 2131 规定此时在 `ciaddr` 填当前地址，而不是填写 requested IP address 选项。默认 T1 为租期一半，但服务器可指定其他值；服务器回应或租约失效会影响后续行为。图中 `(Preferred)` 是地址状态标签，不应理解为一种保证 DHCP 续得同一地址的功能。A 混淆 DNS 与 DHCP；C 请求的不是地址池；D 与图中动态租约不符。'),
903:dict(prompt='Refer to the exhibit. Assume the shown DNS server is the only available DNS resolver, Router A does not provide DNS forwarding, and IP connectivity to the DNS server works. Host A cannot resolve Internet hostnames. What is the configuration problem?',options=[{'label':'A','text':'LAN and WAN network segments are different.'},{'label':'B','text':'Neither configured DNS address points to the available DNS resolver.'},{'label':'C','text':'The default gateway must be the first usable IP address.'},{'label':'D','text':'The host IP address is outside its LAN subnet.'}],explanation='B。图中可用解析器为 196.1.38.132，而主机首选 DNS 配为 192.168.1.254、备用 DNS 配为 196.1.38.254。题设明确路由器不转发 DNS 且只有图中解析器可用，因此两个设置均不能指向该服务。网关 .254 与主机 .1 均处于 192.168.1.0/24；网关不必是首个可用地址，LAN 与 WAN 分属不同网段也正常。DNS 故障不等于所有按 IP 地址访问的互联网通信都失败。'),
904:dict(options=[{'label':'A','text':'bridge'},{'label':'B','text':'monitor'},{'label':'C','text':'rogue detector'},{'label':'D','text':'sniffer'}],explanation='D。Cisco AP 的 sniffer 模式抓取指定信道的无线帧并转发到运行包分析软件的远端主机；支持的工具、封装和限制随平台版本而异。monitor 模式侧重无线监测；bridge 模式用于无线桥接；rogue detector 侧重识别接入有线网络的可疑设备。抓包不保证收到全部空口帧，也不意味着加密内容可自动解密。'),
905:dict(explanation='D。图中 R2 E0/1 的 MAC 为 `12:d8:ba:c2:00:01`，LAN 前缀为 `2001:db8:d955:1008::/64`。在 MAC 中间插入 `ff:fe`，并翻转首字节 U/L 位（0x12 XOR 0x02 = 0x10），得到接口 ID `10d8:baff:fec2:0001`；组合为 `2001:db8:d955:1008:10d8:baff:fec2:1`。A 的首字节及插入值均不对，B/C 的接口 ID 不匹配该 MAC。图中的 2001:db8::/32 是文档示例前缀。'),
906:dict(options=[{'label':'A','text':'Dedicated physical NIC, RAM, disk, and CPU contained inside every VM'},{'label':'B','text':'A guest operating system and applications using virtual CPU, memory, disk, and network devices'},{'label':'C','text':'Only applications running directly on the hypervisor without a guest OS'},{'label':'D','text':'Only configuration files, with no virtual hardware or guest operating system'}],explanation='B。虚拟机通常呈现虚拟 CPU、内存、磁盘及网卡，可在其上运行客户操作系统和应用；hypervisor 在底层为虚拟资源调度或映射物理资源。虚机配置文件和虚拟磁盘保存配置与状态，但不能把它们说成虚机全部运行组件。A 将宿主物理硬件当作每个虚机内部专属组件；C 描述应用直接运行在 hypervisor 而非客户机；D 遗漏客户系统与虚拟硬件。某些部署也支持设备直通，本题询问一般结构。'),
907:dict(prompt='In a Cisco AireOS deployment with a separate AP-manager interface configured, which interface IP address serves as the tunnel source for CAPWAP packets from the controller to an AP?',explanation='C。Cisco AireOS 文档将 AP-manager IP 描述为 WLC 发往 AP 的 CAPWAP 隧道源地址。题目限定使用独立 AP-manager 的部署；其他型号上管理接口也可承担 AP-manager 功能，例如 Cisco 5508 默认如此，因此不能将独立接口说成所有 WLC 的必备组件。A 服务端口主要用于带外管理；B trunk 是链路类型；D 不是题设 AP-manager 接口。'),
908:dict(prompt='For a known unicast frame in a VLAN, which CAM-table information does a switch use to choose the egress port?',explanation='D。交换机按目的 MAC 和所属 VLAN 查找表项，结果给出对应出端口；目的端口是查找结果而非帧中用于查找的字段。源 MAC 和入端口用于学习（C），不是本题的转发查找；老化信息用于维护动态表项（A/B）。若目的 MAC 未知，通常在 VLAN 内符合转发条件的其他端口泛洪；具体还受端口状态和设备功能影响。'),
909:dict(prompt='A FlexConnect AP locally switches tagged client VLANs and carries them with a separate management VLAN over one uplink. Which switch-port mode supports this design?',explanation='A。单条链路需要同时承载多个 VLAN，交换机侧应使用 802.1Q trunk，允许所需 VLAN，并使 AP 与交换机的管理 VLAN 标记/native VLAN 设置一致。B/C 是链路聚合概念，不是承载多 VLAN 所必须的端口模式；D 的普通 access 端口不满足该多 VLAN 设计。若受支持的部署只使用一个 VLAN，FlexConnect 不必一律使用 trunk。'),
910:dict(prompt='Refer to the exhibit. Assume the packet has reached router Y and Y performs a normal destination route lookup for 10.227.151.255. Which next-hop router matches the longest installed route?',explanation='D。图中目的地址与经 Router A 的 `10.0.0.0/8`、经 B 的 `10.128.0.0/9`、经 D 的 `10.224.0.0/11` 均匹配；/11 最长，其下一跳 10.224.4.5 为 Router D。图中经 C 的 `10.224.0.0/15` 只覆盖第二字节 224–225，未覆盖 227；10.127.151.192/27 和 10.226.34.0/24 也不匹配。题目只问 Y 已收到报文后的表项查找，不能由此证明源主机或目的地端到端可达；图中 PC A 与 Y 的所示接口地址还不在同一个 /24。')}
assert sorted(fix)==list(range(901,911))
reasons={901:'确认原图 /23 和最长前缀；压缩冗长解析。',902:'Preferred 是地址状态而非 DHCP 续约功能；修复 RFC 2131 的 ciaddr 错误。',903:'图不能证明 DNS 服务不可达，补充服务与连接前提并限定为配置错误。',904:'修正 rogue 拼写，限定抓包能力并纠正绝对化。',905:'核对图中 MAC、前缀及 EUI-64，注明文档前缀。',906:'原答案只写配置文件不能回答虚机内部组件，改为虚拟设备、客户系统和应用。',907:'限定存在独立 AP-manager 的 AireOS 部署，避免与 5508 管理接口兼任相矛盾。',908:'明确 VLAN 和目的 MAC 是查找键，出口是结果。',909:'明确独立管理 VLAN 与带标签客户 VLAN 同链路，修正 trunk 和 native VLAN 的绝对化。',910:'限定 Y 已收到报文后的查找，说明图示 PC 和 Y 端口 /24 不一致。'}
sources=['https://www.rfc-editor.org/rfc/rfc2131.html','https://www.rfc-editor.org/rfc/rfc3849','https://www.cisco.com/c/en/us/td/docs/wireless/controller/8-7/config-guide/b_cg87/m-packet-capture.html','https://www.cisco.com/c/en/us/td/docs/wireless/controller/8-10/config-guide/b_cg810/ports_and_interfaces.html','https://www.cisco.com/c/en/us/td/docs/wireless/controller/8-5/olh/wlc-olh/contc.html']
items=[]
for n in range(901,911):
 q=by[n]; c=dict(id=n,original_qid=q['qid'],before_sha256=fp(q),reason=reasons[n],updates=fix[n],review=dict(prompt='checked',options='checked',answer='checked and retained',explanation='corrected',image='viewed' if q.get('image') else 'none',code_cli='checked',finding=reasons[n]))
 if q.get('image'):
  f=audit/f'exhibits/q{n}_agent.jpg'; data=base64.b64decode(q['image'].split(',',1)[1]);assert f.read_bytes()==data;c.update(exhibit_path=f'exhibits/{f.name}',image_sha256=hashlib.sha256(data).hexdigest())
 items.append(c)
manifest=dict(scope='Q901-Q910',preserve_question_ids=True,corrections=items,sources=sources,limitations='人工检查图片和文档；未执行真实网络设备或无线控制器实验。')
(audit/'agent-0901-0910.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
lines=['# Q901–Q910 逐题审查','','检查全部题干、选项、答案、解析、原图和代码格式。']
for n in range(901,911):lines.append(f'- Q{n}（{by[n]["qid"]}）：{reasons[n]} 答案保持 {"/".join(by[n]["answer"])}。')
lines+=['','直接查看原图：Q901、Q902、Q903、Q905、Q910。','', '参考资料：']+['- '+u for u in sources]+['','未进行网络设备或控制器实机实验。']
(audit/'agent-0901-0910.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
print('Prepared',len(items),'reviews')
